import type { MetadataRoute } from "next";

/**
 * PWA manifest.
 *
 * Icons are generated by `scripts/generate-icons.mjs` (no image dependencies):
 * a rounded 192/512 pair plus a padded maskable variant, which Android needs so
 * the mark survives its circular/rounded masks.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Bondhu Circle — Find your people in Dhaka",
    short_name: "Bondhu",
    description:
      "Small weekly circles of 4–6 people across Dhaka, with a reason to meet up every week.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#fbfdfc",
    theme_color: "#0f766e",
    categories: ["social", "lifestyle"],
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      {
        src: "/icons/maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
